from pathlib import Path

sources_path = Path('worker/ads-txt-requirement-sources.ts')
source = sources_path.read_text()

old_claim = """function claimExistsSql(alias = 'c'): string {\n  return `EXISTS (\n    SELECT 1 FROM ads_txt_requirement_source_claims ${alias}\n    WHERE ${alias}.publisher_id = ? AND ${alias}.token = ?\n  )`;\n}\n"""
new_claim = """function claimExistsSql(alias = 'c'): string {\n  return `EXISTS (\n    SELECT 1 FROM ads_txt_requirement_source_claims ${alias}\n    WHERE ${alias}.publisher_id = ?\n      AND ${alias}.token = ?\n      AND ${alias}.expires_at > strftime('%Y-%m-%dT%H:%M:%fZ', 'now')\n  )`;\n}\n"""
if old_claim not in source:
    raise SystemExit('claimExistsSql target not found')
source = source.replace(old_claim, new_claim, 1)

update_start = source.index('export async function updateAdsTxtRequirementSource(')
delete_start = source.index('export async function deleteAdsTxtRequirementSource(', update_start)
import_start = source.index('export async function importAdsTxtRequirementSources(', delete_start)

new_update_delete = """export async function updateAdsTxtRequirementSource(\n  request: Request,\n  env: AdsTxtEnv,\n  siteId: string,\n  sourceId: string,\n): Promise<Response> {\n  const db = await ready(env, siteId);\n  if (db instanceof Response) return db;\n\n  let input: SourceInput;\n  try {\n    input = await readJson<SourceInput>(request);\n  } catch (error) {\n    return apiError('Ads.txt requirement could not be updated.', 422, error instanceof Error ? error.message : String(error));\n  }\n\n  const claimToken = await acquireClaim(db, siteId);\n  if (!claimToken) return apiError('Another ads.txt requirement change is already in progress for this site.', 409);\n  try {\n    const current = await sourceRow(db, siteId, sourceId);\n    if (!current) return apiError('Ads.txt requirement not found.', 404);\n\n    let normalized: NormalizedSource;\n    try {\n      normalized = normalizeInput(input, current);\n    } catch (error) {\n      return apiError('Ads.txt requirement could not be updated.', 422, error instanceof Error ? error.message : String(error));\n    }\n\n    const actor = getActor(request);\n    const now = new Date().toISOString();\n    const results = await db.batch([\n      db.prepare(`UPDATE ads_txt_requirement_sources\n        SET source_label = ?, entry = ?, monitor_entry = ?, canonical_entry = ?,\n            required = ?, updated_at = ?\n        WHERE publisher_id = ? AND id = ? AND ${claimExistsSql()}`)\n        .bind(\n          normalized.sourceLabel, normalized.entry, normalized.monitorEntry,\n          normalized.canonicalEntry, normalized.required ? 1 : 0, now,\n          siteId, sourceId, siteId, claimToken,\n        ),\n      ...reconcileStatements(db, siteId, claimToken, now),\n      auditStatement(db, actor, 'ads_txt_requirement_source.updated', siteId, sourceId, {\n        before: toPublicSource(current),\n        after: normalized,\n      }, now, claimToken),\n    ]);\n    if (Number(results[0]?.meta?.changes ?? 0) < 1) {\n      return apiError('The ads.txt requirement change expired before it could be saved. Try again.', 409);\n    }\n    const updated = await sourceRow(db, siteId, sourceId);\n    return json({ ok: true, requirement: updated ? toPublicSource(updated) : null });\n  } finally {\n    await releaseClaim(db, siteId, claimToken).catch(() => undefined);\n  }\n}\n\nexport async function deleteAdsTxtRequirementSource(\n  request: Request,\n  env: AdsTxtEnv,\n  siteId: string,\n  sourceId: string,\n): Promise<Response> {\n  const db = await ready(env, siteId);\n  if (db instanceof Response) return db;\n\n  const claimToken = await acquireClaim(db, siteId);\n  if (!claimToken) return apiError('Another ads.txt requirement change is already in progress for this site.', 409);\n  try {\n    const current = await sourceRow(db, siteId, sourceId);\n    if (!current) return apiError('Ads.txt requirement not found.', 404);\n\n    const actor = getActor(request);\n    const now = new Date().toISOString();\n    const results = await db.batch([\n      db.prepare(`DELETE FROM ads_txt_requirement_sources\n        WHERE publisher_id = ? AND id = ? AND ${claimExistsSql()}`)\n        .bind(siteId, sourceId, siteId, claimToken),\n      ...reconcileStatements(db, siteId, claimToken, now),\n      auditStatement(db, actor, 'ads_txt_requirement_source.deleted', siteId, sourceId, {\n        requirement: toPublicSource(current),\n      }, now, claimToken),\n    ]);\n    if (Number(results[0]?.meta?.changes ?? 0) < 1) {\n      return apiError('The ads.txt requirement change expired before it could be removed. Try again.', 409);\n    }\n    return json({ ok: true, deletedId: sourceId });\n  } finally {\n    await releaseClaim(db, siteId, claimToken).catch(() => undefined);\n  }\n}\n\n"""
source = source[:update_start] + new_update_delete + source[import_start:]

check_marker = 'export async function checkAdsTxtRequirementSources('
check_index = source.index(check_marker)
copy_helper = """export async function copyAdsTxtSourcesForDuplicatedSite(\n  env: AdsTxtEnv,\n  sourceSiteId: string,\n  targetSiteId: string,\n  actor: string,\n): Promise<void> {\n  if (!env.DB) throw new Error('D1 database binding is not configured yet.');\n  await ensureTables(env.DB);\n  if (!await siteExists(env.DB, sourceSiteId)) throw new Error('Source site not found.');\n  if (!await siteExists(env.DB, targetSiteId)) throw new Error('Duplicated target site not found.');\n\n  const source = await sourceRows(env.DB, sourceSiteId);\n  if (!source.length) return;\n  const normalized = source.map((row) => normalizeInput({\n    sourceLabel: row.source_label,\n    entry: row.entry,\n    required: row.required === 1,\n  }));\n  const canonicalCount = new Set(normalized.map((row) => row.canonicalEntry)).size;\n\n  await persistMany(\n    env.DB,\n    targetSiteId,\n    normalized,\n    true,\n    actor,\n    'ads_txt_requirement_sources.site_duplicated',\n    {\n      sourceSiteId,\n      targetSiteId,\n      copied: normalized.length,\n      canonicalRecords: canonicalCount,\n      repeatedRowsPreserved: normalized.length - canonicalCount,\n    },\n  );\n}\n\n"""
source = source[:check_index] + copy_helper + source[check_index:]
sources_path.write_text(source)

app_path = Path('worker/app-ads-txt-duplicate-requirements.ts')
app = app_path.read_text()
app = app.replace(
    '  checkAdsTxtRequirementSources,\n',
    '  checkAdsTxtRequirementSources,\n  copyAdsTxtSourcesForDuplicatedSite,\n',
    1,
)
route_marker = "    const checkMatch = pathname.match(/^\\/api\\/publishers\\/([^/]+)\\/ads-txt\\/check$/);\n"
if route_marker not in app:
    raise SystemExit('app route marker not found')
duplicate_route = """    const siteDuplicateMatch = pathname.match(/^\\/api\\/sites\\/([^/]+)\\/duplicate$/);\n    const legacyDuplicateMatch = pathname.match(/^\\/api\\/publishers\\/([^/]+)\\/duplicate$/);\n    const duplicateMatch = siteDuplicateMatch ?? legacyDuplicateMatch;\n    if (duplicateMatch && request.method === 'POST') {\n      let input: { id?: unknown; copyAdsTxtRequirements?: unknown } = {};\n      try {\n        input = await request.clone().json() as typeof input;\n      } catch {\n        // Let the existing duplication route return its normal validation error.\n      }\n\n      const verified = await authenticatedRequest(request, env);\n      if (verified instanceof Response) return withBuildHeader(verified);\n      const response = await downstream.fetch(verified, env, ctx);\n      const targetSiteId = String(input.id ?? '').trim();\n      if (response.ok && input.copyAdsTxtRequirements === true && targetSiteId) {\n        try {\n          await copyAdsTxtSourcesForDuplicatedSite(\n            env,\n            decodeURIComponent(duplicateMatch[1]),\n            targetSiteId,\n            verified.headers.get('x-user-email') ?? 'unknown',\n          );\n        } catch (error) {\n          return withBuildHeader(apiError(\n            'The site was duplicated, but its complete ads.txt partner rows could not be copied.',\n            502,\n            error instanceof Error ? error.message : String(error),\n          ));\n        }\n      }\n      return withBuildHeader(response);\n    }\n\n"""
app = app.replace(route_marker, duplicate_route + route_marker, 1)
app_path.write_text(app)
